"""hook_pending.py -- warning hooks whose regenerated bytes self-learn could
not place (S-133, gate r2's G2/G4 rule, the orchestrator's decision).

When :func:`verbs.refresh_warn_hooks` has committed a warning hook's new
bytes to the ledger and recompile's host write then fails (a refused host
commit, the dirty gate, a plain-host exclude error), the placed file still
holds the bytes self-learn had placed before, or is missing. This module
records that explicitly, one entry per lesson:

    {"lrn-…": {"placed_sha256": <sha256 of the bytes self-learn had placed,
                                 or null when there were none>,
               "missing": <the file was missing after the failed write>,
               "script_path": <host-relative path>, "at": <iso>, "why": <text>}}

The next maintenance run or recompile places exactly these hooks, and only
when the file is still as that failed write left it: holding
``placed_sha256``, or missing when ``missing`` is true. Anything else is a
person's edit or deletion: left alone and reported. Nothing is inferred
from a file's state alone: a hook that is not recorded here is never
placed by this rule.

Why a cache file, not the ledger record: the entry is about THIS machine's
host write, not about the lesson; writing it needs no extra ledger commit
at the moment a host commit has just failed; and losing it fails safe --
the doctor's hook check reports the placed file not matching the stored
bytes, and nothing is overwritten. Writes are taken under the ledger's
commit lock so two runs never interleave them, through the ledger-write
wrapper (``intents.ledger_write``, S-62 §7.2a.5(1): every acquisition of
the LEDGER's lock goes through it, so an outermost one recovers a
finishable intent or refuses on a STOP before this module writes
anything). ``NOT_REPO_TRUTH``: a file under the XDG cache, never in a
repo.
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .primitives import chrono, fsops

__all__ = ["FILENAME", "SUBDIR", "drop", "path_for", "read", "record"]

SUBDIR = "hooks"
FILENAME = "pending-placements.json"


def path_for(home: Path | str) -> Path:
    """The file, under the per-home cache namespace (read-only resolution:
    computing the path never creates the directory)."""
    from .serve import cache_dir_readonly  # late: serve imports verbs

    return cache_dir_readonly(Path(home)) / SUBDIR / FILENAME


def read(home: Path | str) -> dict[str, dict[str, Any]]:
    """Every recorded entry, ``{}`` when none. Never raises."""
    try:
        data = json.loads(path_for(home).read_text(encoding="utf-8"))
    except (OSError, ValueError, UnicodeDecodeError):
        return {}
    if not isinstance(data, dict):
        return {}
    return {str(k): dict(v) for k, v in data.items() if isinstance(v, dict)}


def _store(home: Path, data: dict[str, dict[str, Any]]) -> None:
    """THE writer (``NOT_REPO_TRUTH``: the XDG cache). Atomic; removes the
    file when nothing is pending."""
    path = path_for(home)
    if not data:
        if path.exists():
            path.unlink()
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    fsops.atomic_write(
        path, json.dumps(data, sort_keys=True, indent=1) + "\n", fsync=False,
        preserve_mode=False,
    )


def _locked_update(home: Path, change, earlier_commits: list[str] | None) -> None:
    """Read, change and store the file under the ledger's commit lock,
    taken through :func:`intents.ledger_write` (a nested take, inside a
    span the caller already holds, is a pass-through). *earlier_commits*:
    the calling verb's own commits from earlier spans of the same run
    (``verbs.recompile``'s), so a STOP refused here reports them, as
    every later span of that verb does (§7.2a.5(4))."""
    from . import intents  # late: keeps this module light

    with intents.ledger_write(home, earlier_commits=earlier_commits) as recovered:
        intents.announce_recovered(recovered)
        data = read(home)
        change(data)
        _store(home, data)


def record(home: Path | str, rid: str, *, placed_sha256: str | None, missing: bool,
           script_path: str, why: str, earlier_commits: list[str] | None = None) -> None:
    """Record one hook whose regenerated bytes could not be placed."""
    entry = {
        "placed_sha256": placed_sha256, "missing": bool(missing),
        "script_path": script_path, "at": chrono.now_iso(), "why": why,
    }
    _locked_update(Path(home), lambda data: data.__setitem__(rid, entry), earlier_commits)


def drop(home: Path | str, rids: list[str], *,
         earlier_commits: list[str] | None = None) -> None:
    """Forget these entries (placed, or no longer a live warning hook)."""
    if not rids:
        return

    def change(data: dict) -> None:
        for rid in rids:
            data.pop(rid, None)

    _locked_update(Path(home), change, earlier_commits)
